package com.kaipai.service.ai.impl;
import com.fasterxml.jackson.databind.*; import com.kaipai.common.exception.BizException; import com.kaipai.model.actor.dto.ProfileDomainErrorCode; import com.kaipai.mapper.ai.AiProfileImportRequestAuditMapper; import com.kaipai.model.ai.dto.*; import com.kaipai.model.ai.entity.*; import com.kaipai.service.ai.*; import com.kaipai.integration.ai.profileimport.DeepSeekProfileTextExtractor; import java.time.LocalDateTime; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.util.StringUtils;
@Service @RequiredArgsConstructor public class ProfileImportServiceImpl implements ProfileImportService { private final ProfileImportConfigService configService; private final DeepSeekProfileTextExtractor extractor; private final AiProfileImportRequestAuditMapper auditMapper; private final ProfileImportRateLimiter rateLimiter; private final ObjectMapper mapper; public ProfileImportExtractionRespDTO extract(Long userId,ProfileImportExtractReqDTO request){var capability=configService.capability();if(!capability.isAvailable())throw ProfileDomainErrorCode.PROFILE_IMPORT_DISABLED.toException();if(request==null||!StringUtils.hasText(request.getRawText()))throw ProfileDomainErrorCode.PROFILE_IMPORT_INPUT_EMPTY.toException();ProfileImportRuntimeConfig runtime=configService.runtimeConfig();if(request.getRawText().length()>runtime.maxInputChars())throw ProfileDomainErrorCode.PROFILE_IMPORT_INPUT_TOO_LONG.toException();if(!rateLimiter.allow(userId,runtime.dailyLimit()))throw ProfileDomainErrorCode.PROFILE_IMPORT_RATE_LIMITED.toException();AiProfileImportConfig config=new AiProfileImportConfig();config.setConfigId(runtime.configId());config.setEndpoint(runtime.endpoint());config.setModelName(runtime.modelName());JsonNode root=extractor.extract(config,runtime.apiKey(),request.getRawText(),request.getRequestId());AiProfileImportRequestAudit audit=new AiProfileImportRequestAudit();audit.setRequestId(request.getRequestId());audit.setUserId(userId);audit.setConfigId(runtime.configId());audit.setModelName(runtime.modelName());audit.setInputLength(request.getRawText().length());audit.setStatus("success");audit.setProfileVersion(request.getProfileVersion());audit.setWorkLibraryVersion(request.getWorkLibraryVersion());audit.setCandidateCount(root.path("profileCandidates").size());audit.setWorkCount(root.path("workCandidates").size());audit.setConflictCount(root.path("conflicts").size());auditMapper.insert(audit);ProfileImportExtractionRespDTO response=new ProfileImportExtractionRespDTO();response.setRequestId(request.getRequestId());response.setProfileCandidateCount(audit.getCandidateCount());response.setWorkCandidateCount(audit.getWorkCount());response.setConflictCount(audit.getConflictCount());return response;} }

